import sys


class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


def build_chain(values):
    head = None
    tail = None
    for v in values:
        node = Node(v)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def chain_values(head):
    out = []
    node = head
    while node is not None:
        out.append(node.value)
        node = node.next
    return out

def delete_first(head, x):
    if head is None:
        return None
    if head.value == x:
        return head.next
    prev = head
    while prev.next is not None:
        if prev.next.value == x:
            prev.next = prev.next.next
            break
        prev = prev.next
    return head


def main():
    sys.setrecursionlimit(100000)

    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    x = int(data[1 + n])
    head = build_chain(values)
    head = delete_first(head, x)
    print(' '.join(map(str, chain_values(head))))


main()

